function HomeView({ actorName, sections, cart, onAdd, onChangeQty, onSetQty, onOpenSection, onOrders, onFavorites, favIds, onToggleFavorite, onRepeatLast, repeating }) {
  const [query, setQuery] = useState("");
  const [debounced, setDebounced] = useState("");
  const { data: banners } = useFetch(() => api.banners(), []);
  const [bannerIndex, setBannerIndex] = useState(0);

  useEffect(() => {
    if (!banners?.length || banners.length < 2) return;
    const t = setInterval(() => setBannerIndex((i) => (i + 1) % banners.length), 5000);
    return () => clearInterval(t);
  }, [banners?.length]);

  useEffect(() => {
    const t = setTimeout(() => setDebounced(query.trim()), 350);
    return () => clearTimeout(t);
  }, [query]);

  // البحث يمر على كل قسم مسموح به — الخادم يمنع ما عداها
  const { data: results, loading, error } = useFetch(
    async (signal) => {
      const all = await Promise.all(
        sections.map((s) => api.products({ sectionId: s.id, search: debounced }, signal).catch(() => []))
      );
      return all.flat();
    },
    [debounced, sections.length],
    { skip: !debounced }
  );

  return (
    <div className="screen">
      <p className="eyebrow-plain">مرحبًا، {actorName}</p>

      {onRepeatLast && (
        <button className="repeat-order-btn" onClick={onRepeatLast} disabled={repeating}>
          <RotateCcw size={16} />
          <span>{repeating ? "جارٍ التكرار…" : "كرر آخر طلبية"}</span>
        </button>
      )}

      {banners?.length > 0 && (() => {
        const b = banners[bannerIndex % banners.length];
        const content = (
          <div className="promo-banner">
            <img src={b.image_url} alt={b.title || ""} />
            {(b.title || b.subtitle) && (
              <div className="promo-banner-text">
                {b.title && <strong>{b.title}</strong>}
                {b.subtitle && <span>{b.subtitle}</span>}
              </div>
            )}
            {banners.length > 1 && (
              <div className="promo-banner-dots">
                {banners.map((_, i) => (
                  <span key={i} className={"promo-dot" + (i === bannerIndex ? " promo-dot-active" : "")} />
                ))}
              </div>
            )}
          </div>
        );
        return b.link_url
          ? <a href={b.link_url} target="_blank" rel="noreferrer" style={{ display: "block", textDecoration: "none" }}>{content}</a>
          : content;
      })()}

      <div className="search-bar">
        <Search size={16} />
        <input placeholder="ابحث عن صنف أو مورد..." value={query} onChange={(e) => setQuery(e.target.value)} />
        {query && <button className="search-clear" onClick={() => setQuery("")} aria-label="مسح"><X size={15} /></button>}
      </div>

      {debounced ? (
        loading ? <Spinner label="جارٍ البحث…" />
        : error ? <ErrorState message={error} />
        : results?.length ? (
          <div className="product-list">
            {(results ?? []).map((p) => (
              <ProductRow key={cartKey(p)} cart={cart} product={p} qty={cart[cartKey(p)]?.qty || 0} onAdd={onAdd} onChangeQty={onChangeQty} onSetQty={onSetQty}
                isFavorite={favIds.has(p.id)} onToggleFavorite={onToggleFavorite} />
            ))}
          </div>
        ) : <div className="center-state"><Search size={22} /><p>لا توجد نتائج مطابقة</p></div>
      ) : (
        <>
          <h2 className="subsection-heading">الأقسام المتاحة لحسابك</h2>
          {sections.length === 0 ? (
            <div className="center-state">
              <Package size={22} />
              <p>لم تُخصَّص لك أقسام بعد — تواصل مع إدارة جملة</p>
            </div>
          ) : (
            <div className="section-grid">
              {sections.map((s) => (
                <button key={s.id} className="section-card" onClick={() => onOpenSection(s)}>
                  {s.image_url
                    ? <img src={s.image_url} alt="" />
                    : <div className="section-card-fallback"><Package size={26} /></div>}
                  <span>{s.name}</span>
                </button>
              ))}
            </div>
          )}
          <button className="past-orders-link" onClick={onOrders}>
            <Clock size={15} /> كشف حسابي ومديونيتي
          </button>
          <button className="past-orders-link" onClick={onFavorites}>
            <Heart size={15} /> الأصناف المفضلة
          </button>
        </>
      )}
    </div>
  );
}

